const API_OPERACIONES_ADMIN = '../Api_Operaciones/api_operaciones.php';
async function apiAdmin(accion, datos = null) { const opciones = { headers: { Accept: 'application/json' } }; if (datos) { opciones.method = 'POST'; opciones.headers['Content-Type'] = 'application/json'; opciones.body = JSON.stringify(datos); } const respuesta = await fetch(`${API_OPERACIONES_ADMIN}?accion=${accion}`, opciones); const resultado = await respuesta.json(); if (!respuesta.ok || !resultado.ok) throw new Error(resultado.mensaje || 'No se pudo completar la operación.'); return resultado; }
function opciones(elemento, datos, valor, texto) { elemento.innerHTML = datos.map((dato) => `<option value="${dato[valor]}">${dato[texto]}</option>`).join('') || '<option value="">Sin datos disponibles</option>'; }
let rutasActivas = [];
function limpiarEdicionRuta() { formRuta.reset(); idRutaAdmin.value = ''; btnGuardarRuta.textContent = 'Crear ruta'; btnCancelarRuta.hidden = true; }
async function cargarAsignaciones() { const [rutas, camiones, conductores, peones, contenedores] = await Promise.all([apiAdmin('rutas'), apiAdmin('camiones'), apiAdmin('trabajadores&rol=conductor'), apiAdmin('trabajadores&rol=peon'), apiAdmin('contenedores')]); rutasActivas = rutas.rutas; opciones(rutaParada, rutas.rutas, 'id_ruta', 'nombre'); opciones(rutaAsignacion, rutas.rutas, 'id_ruta', 'nombre'); opciones(rutaGestion, rutas.rutas, 'id_ruta', 'nombre'); contenedorParada.innerHTML = contenedores.contenedores.map((contenedor) => `<option value="${contenedor.id_contenedor}">${contenedor.ubicacion} · ${contenedor.tipo_residuo} · ${contenedor.capacidad_litros} L</option>`).join('') || '<option value="">No hay contenedores con coordenadas</option>'; camionAsignacion.innerHTML = camiones.camiones.map((c) => `<option value="${c.id_camion}">${c.matricula} · ${c.modelo}</option>`).join(''); opciones(conductorAsignacion, conductores.trabajadores, 'ci', 'nombre'); opciones(peonAsignacion, peones.trabajadores, 'ci', 'nombre'); }
formRuta.addEventListener('submit', async (e) => { e.preventDefault(); try { const editando = idRutaAdmin.value !== ''; const resultado = await apiAdmin(editando ? 'actualizar_ruta' : 'crear_ruta', { id_ruta: idRutaAdmin.value, nombre: nombreRutaAdmin.value, zona: zonaRutaAdmin.value }); mensajeRutas.textContent = resultado.mensaje; limpiarEdicionRuta(); await cargarAsignaciones(); } catch (error) { mensajeRutas.textContent = error.message; } });
btnEditarRuta.addEventListener('click', () => { const ruta = rutasActivas.find((item) => String(item.id_ruta) === rutaGestion.value); if (!ruta) { mensajeRutas.textContent = 'Seleccioná una ruta para modificar.'; return; } idRutaAdmin.value = ruta.id_ruta; nombreRutaAdmin.value = ruta.nombre; zonaRutaAdmin.value = ruta.zona; btnGuardarRuta.textContent = 'Guardar cambios'; btnCancelarRuta.hidden = false; formRuta.scrollIntoView({ behavior: 'smooth', block: 'center' }); });
btnCancelarRuta.addEventListener('click', limpiarEdicionRuta);
btnEliminarRuta.addEventListener('click', async () => { const ruta = rutasActivas.find((item) => String(item.id_ruta) === rutaGestion.value); if (!ruta) { mensajeRutas.textContent = 'Seleccioná una ruta para eliminar.'; return; } if (!confirm(`¿Querés eliminar la ruta ${ruta.nombre}? Dejará de estar disponible para nuevas asignaciones.`)) return; try { mensajeRutas.textContent = (await apiAdmin('eliminar_ruta', { id_ruta: ruta.id_ruta })).mensaje; limpiarEdicionRuta(); await cargarAsignaciones(); } catch (error) { mensajeRutas.textContent = error.message; } });
formParada.addEventListener('submit', async (e) => { const formulario = e.currentTarget; e.preventDefault(); try { mensajeRutas.textContent = (await apiAdmin('crear_parada', { id_ruta: rutaParada.value, id_contenedor: contenedorParada.value, orden: ordenParada.value })).mensaje; formulario.reset(); } catch (error) { mensajeRutas.textContent = error.message; } });
formAsignacion.addEventListener('submit', async (e) => { const formulario = e.currentTarget; e.preventDefault(); try { mensajeRutas.textContent = (await apiAdmin('asignar_ruta', { id_ruta: rutaAsignacion.value, id_camion: camionAsignacion.value, ci_conductor: conductorAsignacion.value, ci_peon: peonAsignacion.value, fecha: fechaAsignacion.value })).mensaje; formulario.reset(); } catch (error) { mensajeRutas.textContent = error.message; } });
apiAdmin('reporte_admin').then(({ reporte }) => { reporteAdmin.textContent = `Rutas asignadas: ${reporte.rutas_hoy} · Paradas recolectadas: ${reporte.recolecciones_hoy} · Incidencias pendientes: ${reporte.incidencias_pendientes} · Ingresos: ${Number(reporte.ingresos_hoy).toLocaleString('es-UY')} kg`; }).catch((error) => { reporteAdmin.textContent = error.message; });
fechaAsignacion.value = new Date().toISOString().slice(0, 10); cargarAsignaciones().catch((error) => { mensajeRutas.textContent = error.message; });
